 const [login,setLogin]=useState(false),[report,setReport]=useState(false),[selected,setSelected]=useState<Incident|null>(null),[shelterEdit,setShelterEdit]=useState<Shelter|boolean>(false),[roadEdit,setRoadEdit]=useState(false),[emergency,setEmergency]=useState(false),[sosOpen,setSosOpen]=useState(false),[mobile,setMobile]=useState(false),[locationEdit,setLocationEdit]=useState(false),[massAlert,setMassAlert]=useState(false),[filter,setFilter]=useState('ALL'),[search,setSearch]=useState(''),[historyYears,setHistoryYears]=useState('all'),[historyState,setHistoryState]=useState('all'),[district,setDistrict]=useState('');
