   if(profile){const notifications=(await api<{items:Notification[]}>('/api/notifications')).items;setAlerts(notifications);await cache('alerts:'+profile.id,notifications);setPending(await queued(profile.id));setPendingSOS(await queuedSOS(profile.id))}
