 async function sendSOS(emergencyType:string,messageText:string){if(!profile){setSosOpen(false);setLogin(true);return}const clientId='sos-'+crypto.randomUUID();const body={...location,emergency_type:emergencyType,message:messageText,client_id:clientId,network_state:navigator.onLine?'online':'offline'};if(!navigator.onLine){const item:PendingSOS={id:clientId,userId:profile.id,body,createdAt:new Date().toISOString(),status:'QUEUED_OFFLINE'};await queueSOS(item);setPendingSOS(await queuedSOS(profile.id));setToast('SOS saved offline. It will be transmitted when internet returns. Call 112/108 now if cellular calling works.');setSosOpen(false);return}try{const sent=await post<SOSEvent>('/api/sos',body);setToast('SOS sent to RiskSetu responders. Status: '+sent.status+'. For immediate emergency help, call 112.');setSosOpen(false)}catch(e){setError(message(e))}}
 async function signout(){try{await post('/api/auth/logout')}catch{}if(supabase)await supabase.auth.signOut();setToken('');sessionStorage.removeItem('risksetu-profile');setProfile(null);setAlerts([]);setOverview(null);setPending([]);navigate('overview')}
